import math

def forward_vols(expiries, vols):
    """Forward volatility between each pair of neighbouring expiries.

    expiries are in years, vols are decimals. A pair whose total
    variance falls gives None instead of a number.
    """
    if len(expiries) != len(vols):
        raise ValueError("one vol per expiry")
    if any(b <= a for a, b in zip(expiries, expiries[1:])):
        raise ValueError("expiries must increase")
    out = []
    for i in range(len(expiries) - 1):
        w1 = vols[i] ** 2 * expiries[i]
        w2 = vols[i + 1] ** 2 * expiries[i + 1]
        if w2 < w1:
            out.append(None)
        else:
            out.append(math.sqrt((w2 - w1) / (expiries[i + 1] - expiries[i])))
    return out

import numpy as np

def first_leak(run, bars, cuts):
    """The smallest cut where rows before the cut change when the
    bars after it are replaced by noise. None if no cut leaks."""
    for cut in sorted(cuts):
        full = run(bars).iloc[:cut].to_numpy(float)
        noisy = run(noise_after(bars, cut)).iloc[:cut].to_numpy(float)
        if full.shape != noisy.shape or not np.allclose(full, noisy, rtol=0, atol=1e-9, equal_nan=True):
            return cut
    return None

